function removeDuplicates(nums: number[]): number {
  // Первые два элемента можно оставить всегда
  if (nums.length <= 2) return nums.length;

  // k — сколько элементов уже записано в «чистую» часть nums[0..k-1]
  let k = 2;

  for (let i = 2; i < nums.length; i++) {
    // Массив отсортирован: если nums[i] совпадает с nums[k - 2],
    // то в чистой части уже есть две такие копии — третью не берём
    if (nums[i] !== nums[k - 2]) {
      nums[k] = nums[i];
      k++;
    }
  }

  return k;
}

// Время: O(n) — один проход
// Память: O(1) — меняем массив на месте
